declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    addRecipe : BOOL;
    deleteRecipe : BOOL;
    modifyRecipe : BOOL;
    queryRecipe : BOOL;
    recipeIn : ST_Recipe;
END_VAR
VAR_OUTPUT
    recipeAdded : BOOL := FALSE;
    recipeDeleted : BOOL := FALSE;
    recipeModified : BOOL := FALSE;
    recipeQueryResult : ST_Recipe;
    error : BOOL := FALSE;
    status : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    recipe : ARRAY[1..10] OF ST_Recipe;
END_VAR
VAR
    prevAdd : BOOL := FALSE;
    prevDelete : BOOL := FALSE;
    prevModify : BOOL := FALSE;
    prevQuery : BOOL := FALSE;
    i : INT;
    matchIdx : INT;
    emptyIdx : INT;
    dupFound : BOOL;
END_VAR

implementation:
recipeAdded := FALSE;
recipeDeleted := FALSE;
recipeModified := FALSE;
error := FALSE;
status := 16#0000;

IF queryRecipe AND NOT prevQuery THEN
    matchIdx := 0;
    IF recipeIn.recipeID <> 0 THEN
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = recipeIn.recipeID THEN
                matchIdx := i;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
    IF matchIdx <> 0 THEN
        recipeQueryResult := recipe[matchIdx];
        error := FALSE;
        status := 16#0000;
    ELSE
        error := TRUE;
        status := 16#8001;
    END_IF;
ELSIF addRecipe AND NOT prevAdd THEN
    dupFound := FALSE;
    IF recipeIn.recipeID <> 0 THEN
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = recipeIn.recipeID THEN
                dupFound := TRUE;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
    IF dupFound THEN
        error := TRUE;
        status := 16#8002;
    ELSE
        emptyIdx := 0;
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = 0 THEN
                emptyIdx := i;
                EXIT;
            END_IF;
        END_FOR;
        IF emptyIdx = 0 THEN
            error := TRUE;
            status := 16#8003;
        ELSE
            recipe[emptyIdx] := recipeIn;
            recipeAdded := TRUE;
            error := FALSE;
            status := 16#0000;
        END_IF;
    END_IF;
ELSIF deleteRecipe AND NOT prevDelete THEN
    matchIdx := 0;
    IF recipeIn.recipeID <> 0 THEN
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = recipeIn.recipeID THEN
                matchIdx := i;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
    IF matchIdx = 0 THEN
        error := TRUE;
        status := 16#8004;
    ELSE
        recipe[matchIdx].recipeID := 0;
        recipeDeleted := TRUE;
        error := FALSE;
        status := 16#0000;
    END_IF;
ELSIF modifyRecipe AND NOT prevModify THEN
    matchIdx := 0;
    IF recipeIn.recipeID <> 0 THEN
        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = recipeIn.recipeID THEN
                matchIdx := i;
                EXIT;
            END_IF;
        END_FOR;
    END_IF;
    IF matchIdx = 0 THEN
        error := TRUE;
        status := 16#8005;
    ELSE
        recipe[matchIdx] := recipeIn;
        recipeModified := TRUE;
        error := FALSE;
        status := 16#0000;
    END_IF;
END_IF;

prevAdd := addRecipe;
prevDelete := deleteRecipe;
prevModify := modifyRecipe;
prevQuery := queryRecipe;

